import { NestFactory } from '@nestjs/core';
import { AppModule } from './app.module';

async function bootstrap() {
  const app = await NestFactory.create(AppModule);
  app.enableCors();
  await app.listen(5000);
}
bootstrap();
</CODE>

### Additional Notes:
1. **Regex Validation**: The `isValidRegex` method in the controller checks if the provided regex pattern is valid. If not, it throws a `BadRequestException`, which results in a 400 response.
2. **Error Handling**: The service method catches errors and throws a generic error message. This can be further improved by differentiating between types of errors (e.g., file not found, permission issues) if needed.
3. **Directory Traversal**: The application does not perform any checks to prevent directory traversal attacks. You may want to implement additional checks to ensure that the `directory` parameter does not allow access to sensitive areas of the filesystem.

Make sure to create a directory named `files` in the root of your project and populate it with some text files for testing the regex search functionality. You can run the application using the command `npm run start`, and it will start a web server on `0.0.0.0:5000`.

